FROM quote q LEFT JOIN content_feature_snapshot fs ON fs.content_id = q.id JOIN quote_tag qt ON qt.quote_id = q.id JOIN tag t ON t.id = qt.tag_id WHERE q.deleted = 0 AND q.status = 1 AND t.name IN
#{tag}
GROUP BY q.id ORDER BY COUNT(DISTINCT t.name) DESC, q.created_time DESC LIMIT #{limit}

